export function up(db) {
  db.exec(`CREATE TABLE comments (
    id TEXT PRIMARY KEY,
    issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
    author_id TEXT NOT NULL REFERENCES users(id),
    body TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX comments_issue ON comments(issue_id,created_at,id);
  CREATE TABLE issue_relations (
    id TEXT PRIMARY KEY,
    source_issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
    target_issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK(kind IN ('blocks','duplicates','relates')),
    created_by TEXT NOT NULL REFERENCES users(id),
    created_at TEXT NOT NULL,
    CHECK(source_issue_id<>target_issue_id),
    UNIQUE(source_issue_id,target_issue_id,kind)
  );
  CREATE INDEX relations_target ON issue_relations(target_issue_id,kind);`);
}

import {AppError,validation} from '@crew/shared';
import {commentInput} from '../../../../shared/src/schemas/discussion.js';
import {analyzeMarkdown} from '../../../../shared/src/markdown.js';
import {getIssue,validateIssueReferences} from './issues.js';
export function mentionedUsers(ctx,issue,body) {
  const handles=new Set(analyzeMarkdown(body).mentions);
  if(!handles.size)return [];
  const members=ctx.db.prepare('SELECT u.id,u.name,u.email FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.org_id=?').all(issue.orgId);
  return members.filter(user=>[user.id,user.name,user.email,user.email.split('@')[0]].some(value=>handles.has(value.toLowerCase()))&&ctx.permissions.canProject(user.id,issue.projectId,'project:read')).map(user=>user.id);
}
export function publicComment(ctx,row) {
  const issue=getIssue(ctx,row.issue_id);
  const author=ctx.db.prepare('SELECT id,name FROM users WHERE id=?').get(row.author_id);
  return {id:row.id,issueId:row.issue_id,projectId:issue.projectId,orgId:issue.orgId,
    authorId:row.author_id,author:{id:author.id,name:author.name},body:row.body,
    html:analyzeMarkdown(row.body).html,mentionedUserIds:mentionedUsers(ctx,issue,row.body),
    createdAt:row.created_at,updatedAt:row.updated_at};
}
export function commentRow(ctx,id) {
  const row=ctx.db.prepare('SELECT * FROM comments WHERE id=?').get(id);
  if(!row)throw new AppError('NOT_FOUND','Comment not found',404);
  return row;
}
export function getComment(ctx,id){return publicComment(ctx,commentRow(ctx,id));}
export function listComments(ctx,issueId) {
  return ctx.db.prepare('SELECT * FROM comments WHERE issue_id=? ORDER BY created_at,id').all(issueId).map(row=>publicComment(ctx,row));
}
function emit(ctx,req,action,before,after,issue) {
  const comment=after??before;
  ctx.bus.emit({actorId:req.user.id,orgId:issue.orgId,projectId:issue.projectId,
    entityType:'comment',entityId:comment.id,action,before:before??null,
    after:after?{...after,issue,mentionedUserIds:after.mentionedUserIds,userIds:after.mentionedUserIds}:null,
    issueId:issue.id,mentionedUserIds:after?.mentionedUserIds??[],time:ctx.now()});
}
export function createComment(ctx,req,issueId,body) {
  const issue=getIssue(ctx,issueId),input=commentInput(body);
  validateIssueReferences(ctx,issue.projectId,{});
  if(!input.body.trim())throw validation({body:'Write a comment before posting'});
  const id=ctx.id(),time=ctx.now();
  ctx.db.prepare('INSERT INTO comments VALUES (?,?,?,?,?,?)').run(id,issueId,req.user.id,input.body,time,time);
  const comment=getComment(ctx,id);emit(ctx,req,'created',null,comment,issue);return comment;
}
export function updateComment(ctx,req,id,body) {
  const before=getComment(ctx,id),issue=getIssue(ctx,before.issueId),input=commentInput(body);
  validateIssueReferences(ctx,issue.projectId,{});
  if(!input.body.trim())throw validation({body:'Write a comment before saving'});
  ctx.db.prepare('UPDATE comments SET body=?,updated_at=? WHERE id=?').run(input.body,ctx.now(),id);
  const after=getComment(ctx,id);emit(ctx,req,'updated',before,after,issue);return after;
}
export function deleteComment(ctx,req,id) {
  const before=getComment(ctx,id),issue=getIssue(ctx,before.issueId);
  validateIssueReferences(ctx,issue.projectId,{});
  ctx.db.prepare('DELETE FROM comments WHERE id=?').run(id);
  emit(ctx,req,'deleted',before,null,issue);return before;
}
export function registerComments(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  function permitted(req,permission='project:read') {
    const issue=getIssue(ctx,req.params.issueId);p.assertProject(req,issue.projectId,permission);return issue;
  }
  function editable(req) {
    const comment=getComment(ctx,req.params.commentId);
    p.assertProject(req,comment.projectId,'comment:write');
    if(comment.authorId!==req.user.id&&!p.canOrg(req.user.id,comment.orgId,'org:manage'))throw new AppError('FORBIDDEN','Only the author or organization administrator may change this comment',403);
    return comment;
  }
  app.get('/api/v1/issues/:issueId/comments',requireAuth,(req,res)=>{
    permitted(req);res.json(ctx.paginate(listComments(ctx,req.params.issueId),req.query));
  });
  app.post('/api/v1/issues/:issueId/comments',requireAuth,(req,res)=>{
    permitted(req,'comment:write');res.status(201).json({comment:createComment(ctx,req,req.params.issueId,req.body)});
  });
  app.patch('/api/v1/comments/:commentId',requireAuth,(req,res)=>{editable(req);res.json({comment:updateComment(ctx,req,req.params.commentId,req.body)});});
  app.delete('/api/v1/comments/:commentId',requireAuth,(req,res)=>{editable(req);deleteComment(ctx,req,req.params.commentId);res.json({ok:true});});
}

import {registerComments} from './comments.js';
import {registerRelations} from './relations.js';
import {AppError} from '@crew/shared';
import {labelInput} from '../../../../shared/src/schemas/issue.js';
import {getIssue,listIssues,createIssue,updateIssue,deleteIssue,publicLabel,validateIssueReferences,emitIssue} from './issues.js';
export function registerIssueRoutes(ctx) {
  registerComments(ctx);
  registerRelations(ctx);
  const {app,db,requireAuth,permissions:p}=ctx;
  const prefix='/api/v1';
  function permitted(req,permission='project:read') {
    const issue=getIssue(ctx,req.params.issueId);
    p.assertProject(req,issue.projectId,permission);
    return issue;
  }
  app.get(prefix+'/projects/:projectId/issues',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'project:read');
    res.json(ctx.paginate(listIssues(ctx,req.params.projectId,req.query),req.query));
  });
  app.get(prefix+'/orgs/:orgId/issues',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'org:read');p.scope(req,'project:read');
    const projects=p.projectIds(req.user.id,req.params.orgId);
    const issues=projects.flatMap(projectId=>listIssues(ctx,projectId,req.query)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)||a.id.localeCompare(b.id));
    res.json(ctx.paginate(issues,req.query));
  });
  app.post(prefix+'/projects/:projectId/issues',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'issue:write');
    res.status(201).json({issue:createIssue(ctx,req,req.params.projectId,req.body)});
  });
  app.get(prefix+'/issues/:issueId',requireAuth,(req,res)=>res.json({issue:permitted(req)}));
  app.patch(prefix+'/issues/:issueId',requireAuth,(req,res)=>{
    permitted(req,'issue:write');res.json({issue:updateIssue(ctx,req,req.params.issueId,req.body)});
  });
  app.delete(prefix+'/issues/:issueId',requireAuth,(req,res)=>{
    permitted(req,'issue:write');deleteIssue(ctx,req,req.params.issueId);res.json({ok:true});
  });
  app.get(prefix+'/projects/:projectId/labels',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'project:read');
    res.json(ctx.paginate(db.prepare('SELECT * FROM labels WHERE project_id=? ORDER BY name,id').all(req.params.projectId).map(publicLabel),req.query));
  });
  app.post(prefix+'/projects/:projectId/labels',requireAuth,(req,res)=>{
    const project=p.assertProject(req,req.params.projectId,'issue:write');
    validateIssueReferences(ctx,project.id,{});
    const input=labelInput(req.body),id=ctx.id(),time=ctx.now();
    if(db.prepare('SELECT 1 FROM labels WHERE project_id=? AND name=?').get(project.id,input.name))throw new AppError('CONFLICT','Label name already exists',409);
    db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run(id,project.id,input.name,input.color,time,time);
    const label=publicLabel(db.prepare('SELECT * FROM labels WHERE id=?').get(id));
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:id,action:'created',before:null,after:label,time});
    res.status(201).json({label});
  });
  function editableLabel(req) {
    const row=db.prepare('SELECT * FROM labels WHERE id=?').get(req.params.labelId);
    if(!row)throw new AppError('NOT_FOUND','Label not found',404);
    const project=p.assertProject(req,row.project_id,'issue:write');
    validateIssueReferences(ctx,project.id,{});
    return {row,project};
  }
  app.patch(prefix+'/labels/:labelId',requireAuth,(req,res)=>{
    const {row,project}=editableLabel(req),input=labelInput(req.body,{partial:true});
    if(input.name&&db.prepare('SELECT 1 FROM labels WHERE project_id=? AND name=? AND id<>?').get(project.id,input.name,row.id))throw new AppError('CONFLICT','Label name already exists',409);
    const affected=db.prepare('SELECT issue_id FROM issue_labels WHERE label_id=?').all(row.id).map(item=>getIssue(ctx,item.issue_id));
    db.prepare('UPDATE labels SET name=?,color=?,updated_at=? WHERE id=?').run(input.name??row.name,input.color??row.color,ctx.now(),row.id);
    const label=publicLabel(db.prepare('SELECT * FROM labels WHERE id=?').get(row.id));
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:row.id,action:'updated',before:publicLabel(row),after:label,time:ctx.now()});
    for(const before of affected)emitIssue(ctx,req,'updated',before,getIssue(ctx,before.id));
    res.json({label});
  });
  app.delete(prefix+'/labels/:labelId',requireAuth,(req,res)=>{
    const {row,project}=editableLabel(req);
    const affected=db.prepare('SELECT issue_id FROM issue_labels WHERE label_id=?').all(row.id).map(item=>getIssue(ctx,item.issue_id));
    db.prepare('DELETE FROM labels WHERE id=?').run(row.id);
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:row.id,action:'deleted',before:publicLabel(row),after:null,time:ctx.now()});
    for(const before of affected)emitIssue(ctx,req,'updated',before,getIssue(ctx,before.id));
    res.json({ok:true});
  });
}

import {AppError,validation} from '@crew/shared';
import {relationInput,relationPair,relationCaption} from '../../../../shared/src/schemas/discussion.js';
import {getIssue,validateIssueReferences} from './issues.js';
export function publicRelation(ctx,row,viewIssueId=row.source_issue_id) {
  const outgoing=row.source_issue_id===viewIssueId;
  const direction=row.kind==='relates'?'both':outgoing?'outgoing':'incoming';
  const relatedIssue=getIssue(ctx,outgoing?row.target_issue_id:row.source_issue_id);
  return {id:row.id,sourceIssueId:row.source_issue_id,targetIssueId:row.target_issue_id,
    kind:row.kind,direction,caption:relationCaption(row.kind,direction),relatedIssue,
    createdBy:row.created_by,createdAt:row.created_at};
}
export function relationRow(ctx,id) {
  const row=ctx.db.prepare('SELECT * FROM issue_relations WHERE id=?').get(id);
  if(!row)throw new AppError('NOT_FOUND','Relation not found',404);return row;
}
export function listRelations(ctx,req,issueId) {
  return ctx.db.prepare('SELECT * FROM issue_relations WHERE source_issue_id=? OR target_issue_id=? ORDER BY created_at,id').all(issueId,issueId)
    .filter(row=>ctx.permissions.canProject(req.user.id,getIssue(ctx,row.source_issue_id===issueId?row.target_issue_id:row.source_issue_id).projectId,'project:read'))
    .map(row=>publicRelation(ctx,row,issueId));
}
function wouldCycle(ctx,sourceId,targetId,kind) {
  const seen=new Set(),pending=[targetId];
  while(pending.length){
    const current=pending.pop();if(current===sourceId)return true;
    if(seen.has(current))continue;seen.add(current);
    for(const row of ctx.db.prepare('SELECT target_issue_id FROM issue_relations WHERE source_issue_id=? AND kind=?').all(current,kind))pending.push(row.target_issue_id);
  }
  return false;
}
function emit(ctx,req,action,before,after,issue) {
  const relation=after??before;
  ctx.bus.emit({actorId:req.user.id,orgId:issue.orgId,projectId:issue.projectId,
    entityType:'relation',entityId:relation.id,action,before:before??null,after:after??null,
    issueId:issue.id,time:ctx.now()});
}
export function createRelation(ctx,req,issueId,body) {
  const input=relationInput(body),source=getIssue(ctx,issueId),target=getIssue(ctx,input.targetIssueId);
  ctx.permissions.assertProject(req,target.projectId,'issue:write');
  if(source.orgId!==target.orgId)throw validation({targetIssueId:'Related issues must belong to the same organization'});
  validateIssueReferences(ctx,source.projectId,{});validateIssueReferences(ctx,target.projectId,{});
  const [from,to]=relationPair(issueId,target.id,input.kind);
  if(ctx.db.prepare('SELECT 1 FROM issue_relations WHERE source_issue_id=? AND target_issue_id=? AND kind=?').get(from,to,input.kind))throw new AppError('CONFLICT','This relation already exists',409);
  if(input.kind!=='relates'&&wouldCycle(ctx,from,to,input.kind))throw validation({targetIssueId:'This relation would create a '+input.kind+' cycle'});
  if(input.kind==='duplicates'&&ctx.db.prepare("SELECT 1 FROM issue_relations WHERE source_issue_id=? AND kind='duplicates'").get(from))throw new AppError('CONFLICT','An issue can duplicate only one original issue',409);
  const id=ctx.id();ctx.db.prepare('INSERT INTO issue_relations VALUES (?,?,?,?,?,?)').run(id,from,to,input.kind,req.user.id,ctx.now());
  const relation=publicRelation(ctx,relationRow(ctx,id),issueId);emit(ctx,req,'created',null,relation,source);return relation;
}
export function registerRelations(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/issues/:issueId/relations',requireAuth,(req,res)=>{
    const issue=getIssue(ctx,req.params.issueId);p.assertProject(req,issue.projectId,'project:read');res.json(ctx.paginate(listRelations(ctx,req,issue.id),req.query));
  });
  app.post('/api/v1/issues/:issueId/relations',requireAuth,(req,res)=>{
    const issue=getIssue(ctx,req.params.issueId);p.assertProject(req,issue.projectId,'issue:write');res.status(201).json({relation:createRelation(ctx,req,issue.id,req.body)});
  });
  app.delete('/api/v1/relations/:relationId',requireAuth,(req,res)=>{
    const row=relationRow(ctx,req.params.relationId),source=getIssue(ctx,row.source_issue_id),target=getIssue(ctx,row.target_issue_id);
    p.assertProject(req,source.projectId,'issue:write');p.assertProject(req,target.projectId,'issue:write');
    validateIssueReferences(ctx,source.projectId,{});validateIssueReferences(ctx,target.projectId,{});
    const before=publicRelation(ctx,row);ctx.db.prepare('DELETE FROM issue_relations WHERE id=?').run(row.id);emit(ctx,req,'deleted',before,null,source);res.json({ok:true});
  });
}

export * from './errors.js';
export * from './validate.js';
export * from './events.js';
export * from './schemas/user.js';
export * from './permissions.js';
export * from './schemas/org.js';
export * from './schemas/issue.js';
export * from './schemas/project.js';
export * from './markdown.js';
export * from './schemas/discussion.js';

export function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
}
export function safeMarkdownUrl(value) {
  try {
    if(typeof value!=='string'||/[\u0000-\u0020\u007f]/.test(value))return null;
    const url=new URL(value);
    return ['http:','https:','mailto:'].includes(url.protocol)?url.href:null;
  }catch{return null;}
}
function inline(source,mentions,depth=0) {
  let html='',position=0;
  while(position<source.length){
    const remaining=source.slice(position);
    if(remaining[0]==='\\'&&remaining.length>1){html+=escapeHtml(remaining[1]);position+=2;continue;}
    if(remaining[0]==='`'){
      const end=source.indexOf('`',position+1);
      if(end>position){html+='<code>'+escapeHtml(source.slice(position+1,end))+'</code>';position=end+1;continue;}
    }
    const mention=remaining.match(/^@\[([^\]]{1,120})\]\(user:([^\s)]+)\)/);
    if(mention){
      mentions.push(mention[2]);html+='<span class="mention" data-user-id="'+escapeHtml(mention[2])+'">@'+escapeHtml(mention[1])+'</span>';position+=mention[0].length;continue;
    }
    const direct=remaining.match(/^@\{([^}\s]{1,128})\}/);
    const handle=remaining.match(/^@([A-Za-z0-9_.+%-]+(?:@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?)/);
    if((direct||handle)&&(position===0||!/[\w@]/.test(source[position-1]))){
      const match=direct??handle;mentions.push(match[1]);html+='<span class="mention">@'+escapeHtml(match[1])+'</span>';position+=match[0].length;continue;
    }
    const link=remaining.match(/^\[([^\]\n]{1,500})\]\(([^\s)]+)\)/);
    if(link){
      const url=safeMarkdownUrl(link[2]);
      html+=url?'<a href="'+escapeHtml(url)+'" rel="noopener noreferrer">'+escapeHtml(link[1])+'</a>':escapeHtml(link[0]);
      position+=link[0].length;continue;
    }
    let formatted=false;
    if(depth<8)for(const [marker,tag] of [['**','strong'],['__','strong'],['~~','del'],['*','em'],['_','em']]){
      if(!remaining.startsWith(marker))continue;
      const end=source.indexOf(marker,position+marker.length);
      if(end<=position+marker.length)continue;
      html+='<'+tag+'>'+inline(source.slice(position+marker.length,end),mentions,depth+1)+'</'+tag+'>';
      position=end+marker.length;formatted=true;break;
    }
    if(formatted)continue;
    html+=escapeHtml(source[position]);position++;
  }
  return html;
}
export function analyzeMarkdown(value) {
  const lines=String(value??'').replace(/\r\n?/g,'\n').split('\n');
  const mentions=[],blocks=[];
  let index=0;
  const isBlock=line=>/^\s*$|^#{1,6}\s|^\s*```|^>\s?|^\s*[-*+]\s|^\s*\d+\.\s|^\s*(?:---+|\*\*\*+)\s*$/.test(line);
  while(index<lines.length){
    const line=lines[index];
    if(!line.trim()){index++;continue;}
    const fence=line.match(/^\s*```([A-Za-z0-9_-]*)\s*$/);
    if(fence){
      const code=[];index++;
      while(index<lines.length&&!/^\s*```\s*$/.test(lines[index]))code.push(lines[index++]);
      if(index<lines.length)index++;
      blocks.push('<pre><code'+(fence[1]?' class="language-'+fence[1]+'"':'')+'>'+escapeHtml(code.join('\n'))+'</code></pre>');continue;
    }
    const heading=line.match(/^(#{1,6})\s+(.+)$/);
    if(heading){const tag='h'+heading[1].length;blocks.push('<'+tag+'>'+inline(heading[2],mentions)+'</'+tag+'>');index++;continue;}
    if(/^\s*(?:---+|\*\*\*+)\s*$/.test(line)){blocks.push('<hr>');index++;continue;}
    if(/^>/.test(line)){
      const quoted=[];while(index<lines.length&&/^>/.test(lines[index]))quoted.push(inline(lines[index++].replace(/^>\s?/,''),mentions));
      blocks.push('<blockquote><p>'+quoted.join('<br>')+'</p></blockquote>');continue;
    }
    const list=line.match(/^\s*([-*+]|\d+\.)\s+(.+)$/);
    if(list){
      const ordered=/\d/.test(list[1]);const items=[];
      while(index<lines.length){
        const item=lines[index].match(/^\s*([-*+]|\d+\.)\s+(.+)$/);
        if(!item||/\d/.test(item[1])!==ordered)break;
        const task=item[2].match(/^\[([ xX])\]\s+(.*)$/);
        const content=task?'<input type="checkbox" disabled'+(task[1].toLowerCase()==='x'?' checked':'')+' aria-label="'+(task[1]===' '?'Incomplete':'Complete')+' task"> '+inline(task[2],mentions):inline(item[2],mentions);
        items.push('<li>'+content+'</li>');index++;
      }
      const tag=ordered?'ol':'ul';blocks.push('<'+tag+'>'+items.join('')+'</'+tag+'>');continue;
    }
    const paragraph=[inline(line,mentions)];index++;
    while(index<lines.length&&!isBlock(lines[index]))paragraph.push(inline(lines[index++],mentions));
    blocks.push('<p>'+paragraph.join('<br>')+'</p>');
  }
  return {html:blocks.join('\n'),mentions:[...new Set(mentions.map(value=>value.toLowerCase()))]};
}
export function renderMarkdown(value){return analyzeMarkdown(value).html;}
export function extractMentions(value){return analyzeMarkdown(value).mentions;}

import {fields,text,choice} from '../validate.js';
import {validation} from '../errors.js';
export const RELATION_KINDS=Object.freeze(['blocks','duplicates','relates']);
export function commentInput(body) {
  fields(body,['body']);
  return {body:text(body.body,'body',{max:100000,trim:false})};
}
export function relationInput(body) {
  fields(body,['targetIssueId','kind']);
  return {targetIssueId:text(body.targetIssueId,'targetIssueId',{max:128}),kind:choice(body.kind,'kind',RELATION_KINDS)};
}
export function relationPair(sourceId,targetId,kind) {
  if(sourceId===targetId)throw validation({targetIssueId:'An issue cannot relate to itself'});
  return kind==='relates'&&sourceId>targetId?[targetId,sourceId]:[sourceId,targetId];
}
export function relationCaption(kind,direction) {
  if(kind==='relates')return 'relates to';
  if(kind==='blocks')return direction==='incoming'?'blocked by':'blocks';
  if(kind==='duplicates')return direction==='incoming'?'duplicated by':'duplicates';
  return kind;
}
